@code {
    private List<Channel>? channels;
    private int activeChannelId;
    private Channel? activeChannel;

    private List<Message>? messages;
    private Dictionary<int, ThreadSummary> threadSummaries = new();
    private int messageSkip;
    private const int PageSize = 30;
    private bool isLoadingMore;
    private bool allMessagesLoaded;

    private string newMessageText = "";

    // Thread panel
    private bool threadOpen;
    private Message? threadRootMessage;
    private List<Message>? threadReplies;
    private string threadReplyText = "";

    // UI state
    private int? hoveredMessageId;
    private int? emojiPickerMessageId;
    private ElementReference messageListRef;
    private ElementReference threadListRef;

    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "🚀", "👀"];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await SelectChannelAsync(channels[0]);
        }
    }

    private async Task SelectChannelAsync(Channel channel)
    {
        if (activeChannelId == channel.Id && messages is not null) return;

        activeChannelId = channel.Id;
        activeChannel = channel;
        messageSkip = 0;
        allMessagesLoaded = false;
        messages = null;
        threadSummaries.Clear();

        var loaded = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        messages = loaded;
        messageSkip = loaded.Count;
        BuildThreadSummaries(loaded);

        await ChatService.MarkChannelReadAsync(channel.Id);
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadOlderMessagesAsync()
    {
        if (isLoadingMore || allMessagesLoaded) return;

        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(activeChannelId, messageSkip, PageSize);
        if (older.Count == 0)
        {
            allMessagesLoaded = true;
        }
        else
        {
            messages = [..older, ..messages!];
            messageSkip += older.Count;
            BuildThreadSummaries(older);
        }

        isLoadingMore = false;
    }

    private async Task OnMessageListScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", "document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop < 50)
        {
            await LoadOlderMessagesAsync();
        }
    }

    private async Task SendMessageAsync()
    {
        if (string.IsNullOrWhiteSpace(newMessageText)) return;

        var sent = await ChatService.SendMessageAsync(activeChannelId, newMessageText.Trim(), null);
        messages ??= [];
        messages.Add(sent);
        messageSkip++;
        newMessageText = "";

        await ScrollToBottomAsync(messageListRef);
    }

    private async Task OnMessageKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendMessageAsync();
        }
    }

    // ── Thread ──

    private async Task OpenThreadAsync(Message rootMessage)
    {
        threadRootMessage = rootMessage;
        threadReplyText = "";
        emojiPickerMessageId = null;

        threadReplies = await ChatService.GetThreadAsync(rootMessage.Id);
        threadOpen = true;
    }

    private void CloseThread()
    {
        threadOpen = false;
        threadRootMessage = null;
        threadReplies = null;
        threadReplyText = "";
    }

    private async Task SendThreadReplyAsync()
    {
        if (string.IsNullOrWhiteSpace(threadReplyText) || threadRootMessage is null) return;

        var reply = await ChatService.SendMessageAsync(activeChannelId, threadReplyText.Trim(), threadRootMessage.Id);
        threadReplies ??= [];
        threadReplies.Add(reply);
        threadReplyText = "";

        // Update the thread summary in the main message list
        if (threadSummaries.ContainsKey(threadRootMessage.Id))
        {
            var existing = threadSummaries[threadRootMessage.Id];
            threadSummaries[threadRootMessage.Id] = existing with
            {
                ReplyCount = existing.ReplyCount + 1,
                LastReplyAt = reply.SentAt
            };
        }
        else
        {
            threadSummaries[threadRootMessage.Id] = new ThreadSummary(threadRootMessage.Id, 1, reply.SentAt);
        }

        await ScrollToBottomAsync(threadListRef);
    }

    private async Task OnThreadKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await SendThreadReplyAsync();
        }
    }

    // ── Reactions ──

    private async Task ReactAsync(int messageId, string emoji)
    {
        await ChatService.AddReactionAsync(messageId, emoji);
        emojiPickerMessageId = null;

        // Refresh messages to reflect the new reaction
        if (messages is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(activeChannelId, 0, messages.Count);
            messages = refreshed;
        }

        // Refresh thread replies if open
        if (threadOpen && threadRootMessage is not null)
        {
            threadReplies = await ChatService.GetThreadAsync(threadRootMessage.Id);
        }
    }

    private void ToggleEmojiPicker(int messageId)
    {
        emojiPickerMessageId = emojiPickerMessageId == messageId ? null : messageId;
    }

    // ── Helpers ──

    private void BuildThreadSummaries(List<Message> msgs)
    {
        // Messages with ReplyToId reference their root; group them.
        var replies = msgs.Where(m => m.ReplyToId.HasValue).GroupBy(m => m.ReplyToId!.Value);
        foreach (var g in replies)
        {
            var count = g.Count();
            var lastReply = g.Max(m => m.SentAt);
            if (threadSummaries.TryGetValue(g.Key, out var existing))
            {
                threadSummaries[g.Key] = new ThreadSummary(g.Key,
                    existing.ReplyCount + count,
                    lastReply > existing.LastReplyAt ? lastReply : existing.LastReplyAt);
            }
            else
            {
                threadSummaries[g.Key] = new ThreadSummary(g.Key, count, lastReply);
            }
        }
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt.ToUniversalTime();
        if (diff.TotalSeconds < 60) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private static string TruncateDescription(string desc)
    {
        return desc.Length <= 50 ? desc : desc[..47] + "…";
    }

    private async Task ScrollToBottomAsync(ElementReference el)
    {
        try
        {
            await JS.InvokeVoidAsync("eval", $"document.querySelector('.message-list')&&(document.querySelector('.message-list').scrollTop=document.querySelector('.message-list').scrollHeight)");
        }
        catch
        {
            // Element may not exist yet
        }
    }
}
